INSERT INTO `comic` VALUES (1,'海贼王','尾田荣一郎','/images/1001/cover.jpg','连载','热血 · 冒险','讲述蒙奇·D·路飞与伙伴们为寻找传说中的 ONE PIECE 而展开的大航海冒险故事。','a614ede66b99cd20','demo_source','1001','更新至 1080 话','2026-09-02T12:06:55'),(2,'进击的巨人','谏山创','/images/1002/cover.jpg','完结','悬疑 · 战斗','人类与巨人的生存之战，少年艾伦为夺回自由而战的史诗级故事。','e40769dc97b3c972','demo_source','1002','全 139 话','2026-09-02T12:06:56'),(3,'咒术回战','芥见下下','/images/1003/cover.jpg','连载','校园 · 战斗','高中生虎杖悠仁吞下诅咒之王的手指，踏入咒术师世界的战斗物语。','67fecef07422de53','demo_source','1003','更新至 268 话','2026-09-02T12:06:56'),(4,'鬼灭之刃','吾峠呼世晴','/images/2002/cover.jpg','完结','热血 · 奇幻','少年炭治郎为拯救变成鬼的妹妹，加入鬼杀队踏上斩鬼之旅的热血物语。','f337b530f2e728ec','demo_source_b','2002','全 205 话','2026-09-02T10:14:47'),(13,'Pepper & Carrot','David Revoy','covers/13.jpg','连载','奇幻 · 冒险','Pepper & Carrot 是画师 David Revoy 创作的开源 webcomic，全站采用 CC-BY 4.0 许可（可自由分享与改编，需署名作者）。本条为真实源站抓取演示数据：调度 → 抓取 → 解析 → 去重 → 入库 → 懒转存，全链路真实可跑。','56112ef3f3390a97','peppercarrot','pepper-and-carrot','Episode 39: The Tavern','2026-09-02T12:05:22'),(22,'喜欢的冲绳妹说方言','','covers/22.jpg','连载','校园 / 恋爱','喜欢的妹子总是说冲绳方言','de644ca2a73db106','guazi','31088','第1256话 蚂蚁虚空','2026-09-02T14:59:03'),(23,'被冷待的皇子是天才链金术师','','covers/23.jpg','连载','奇幻','某天，一个向往着和睦家庭的男人，转生到了魔法发达的伊斯卡利昂帝国。 他的名字叫亚夏。身为不受宠的第一皇子，因为血统的关系无法成为嫡长子，甚至注定会被自己最爱的弟弟们疏远。 既然如此，他干脆将皇位让给二弟，无拘无束地投入自己的爱好「炼金术」之...','e2e9b4f2fc957f7c','guazi','35488','第998话 毒计反噬','2026-09-02T14:59:13'),(26,'午夜心旋律','五十岚正邦','covers/26.jpg','连载中','爱情, 校园','这次的故事从“声音”开始。高中生山吹有恓为了寻找初中时沉迷的电台主播而专注于声音。某天从学校广播中听到了确信是本人的声音。但是冲到广播室才发现有四个人在内，而且梦想也能对应上，为了找出真身告诉她自己的心意，有恓开始了行动','72ba008db5fea15f','zaimanhua','71419','第128话','2026-09-02T17:50:49');
